package com.gathin.tvhome;

import android.app.Activity;
import android.app.AlertDialog;
import android.graphics.Color;
import android.graphics.drawable.GradientDrawable;
import android.os.Bundle;
import android.os.Handler;
import android.os.Looper;
import android.view.Gravity;
import android.view.KeyEvent;
import android.view.View;
import android.widget.Button;
import android.widget.LinearLayout;
import android.widget.ImageView;
import android.widget.ScrollView;
import android.widget.TextView;
import java.text.SimpleDateFormat;
import java.util.Calendar;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class PanchangActivity extends Activity {
    private static final TimeZone IST=TimeZone.getTimeZone("Asia/Kolkata");
    private final ExecutorService worker=Executors.newSingleThreadExecutor();
    private final Handler main=new Handler(Looper.getMainLooper());
    private final Runnable todayRefresh=()->render();
    private Calendar selected=Calendar.getInstance(IST); private LinearLayout content,actions; private TextView loading; private boolean pickerOpen; private int generation;
    @Override public void onCreate(Bundle b){super.onCreate(b);selected.set(Calendar.HOUR_OF_DAY,12);build();content.requestFocus();render();}
    private int dp(float v){return (int)(v*getResources().getDisplayMetrics().density+.5f);}
    private TextView label(String s,int size,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextColor(Color.WHITE);t.setTextSize(size);t.setPadding(dp(8),dp(4),dp(8),dp(4));t.setFontFeatureSettings("kern");if(bold)t.setTypeface(android.graphics.Typeface.DEFAULT,android.graphics.Typeface.BOLD);return t;}
    private void build(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(36),dp(20),dp(36),dp(16));root.setBackgroundColor(Color.BLACK);setContentView(root);loading=label("Panchang",28,true);root.addView(loading);ScrollView sc=new ScrollView(this);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setFocusable(true);sc.addView(content);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));actions=new LinearLayout(this);actions.setGravity(Gravity.CENTER);root.addView(actions);String[] names={"Previous day","Today","Pick date","Next day"};for(int i=0;i<names.length;i++){final int which=i;Button b=new Button(this);b.setText(names[i]);b.setFocusable(true);b.setOnClickListener(v->{if(which==0)addDay(-1);else if(which==1){selected=Calendar.getInstance(IST);render();}else if(which==2)openPicker();else addDay(1);});actions.addView(b,new LinearLayout.LayoutParams(0,dp(54),1));} }
    private void addDay(int n){selected.add(Calendar.DAY_OF_MONTH,n);render();}
    @Override public boolean dispatchKeyEvent(KeyEvent e){if(e.getAction()==KeyEvent.ACTION_DOWN&&!pickerOpen){View f=getCurrentFocus();boolean onActions=false;while(f!=null){if(f==actions){onActions=true;break;}android.view.ViewParent p=f.getParent();f=p instanceof View?(View)p:null;}if(!onActions&&e.getKeyCode()==KeyEvent.KEYCODE_DPAD_LEFT){addDay(-1);return true;}if(!onActions&&e.getKeyCode()==KeyEvent.KEYCODE_DPAD_RIGHT){addDay(1);return true;}}return super.dispatchKeyEvent(e);}
    private void render(){final int y=selected.get(Calendar.YEAR),m=selected.get(Calendar.MONTH)+1,d=selected.get(Calendar.DAY_OF_MONTH),request=++generation;loading.setText("Loading Panchang...");worker.execute(()->{Panchang.DayEvents data=new Panchang.DayEvents(y,m,d);main.post(()->{if(request==generation)show(data);});});}
    private String nextDate(Calendar next){SimpleDateFormat f=new SimpleDateFormat("MMM d",Locale.US);f.setTimeZone(IST);return f.format(next.getTime());}
    private String tm(double jd){if(Double.isNaN(jd))return "";SimpleDateFormat f=new SimpleDateFormat("h:mm a",Locale.US);f.setTimeZone(IST);return f.format(new Date((long)((jd-2440587.5)*86400000)));}
    private String timed(double jd,int y,int m,int d){if(Double.isNaN(jd))return "Not available";Calendar c=(Calendar)selected.clone();c.set(y,m-1,d,0,0,0);double dayStart=Panchang.julianDay(y,m,d,0,0)-5.5/24.0;String out=tm(jd);if(jd>=dayStart+1){Calendar next=(Calendar)c.clone();next.add(Calendar.DAY_OF_MONTH,1);out+=", "+nextDate(next);}return out;}
    private void row(LinearLayout col,String title,String value){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(8),dp(6),dp(8),dp(6));TextView a=label(title,15,true),b=label(value,19,false);box.addView(a);box.addView(b);col.addView(box);}
    private String after(double end,java.util.function.DoubleFunction<String> name,java.util.function.DoubleFunction<Double> nextEnd,int y,int m,int d){double t=end+0.00001;return "till "+timed(end,y,m,d)+", then "+name.apply(t)+" till "+timed(nextEnd.apply(t),y,m,d);}
    private String afterTwice(double end,java.util.function.DoubleFunction<String> name,java.util.function.DoubleFunction<Double> nextEnd,int y,int m,int d){double t=end+0.00001,n=nextEnd.apply(t);return "till "+timed(end,y,m,d)+", then "+name.apply(t)+" till "+timed(n,y,m,d)+", then "+name.apply(n+0.00001);}
    private void show(Panchang.DayEvents e){content.removeAllViews();int y=selected.get(Calendar.YEAR),m=selected.get(Calendar.MONTH)+1,d=selected.get(Calendar.DAY_OF_MONTH);SimpleDateFormat headerFormat=new SimpleDateFormat("EEEE, d MMMM yyyy",Locale.US);headerFormat.setTimeZone(IST);String greg=headerFormat.format(selected.getTime());loading.setText("Panchang  \u00B7  "+greg);LinearLayout cols=new LinearLayout(this);content.addView(cols);LinearLayout[] c=new LinearLayout[3];for(int i=0;i<3;i++){c[i]=new LinearLayout(this);c[i].setOrientation(LinearLayout.VERTICAL);cols.addView(c[i],new LinearLayout.LayoutParams(0,-2,1));}
        Calendar wd=(Calendar)selected.clone();String[] hindi={"","Ravivara","Somavara","Mangalavara","Budhavara","Guruvara","Shukravara","Shanivara"};row(c[0],"Hindu date",e.base.monthDisplay+" (Amanta), "+e.base.paksha+" Paksha");row(c[0],"Samvat", "Vikram "+e.base.vikramSamvat+"  \u00B7  Shaka "+e.base.shakaSamvat);row(c[0],"Weekday",new SimpleDateFormat("EEEE",Locale.US).format(selected.getTime())+"  \u00B7  "+hindi[wd.get(Calendar.DAY_OF_WEEK)]);row(c[0],"Sunrise / sunset",tm(e.base.sunriseJd)+" / "+tm(e.sunset));row(c[0],"Moonrise / moonset",(Double.isNaN(e.moonrise)?"No moonrise today":timed(e.moonrise,y,m,d))+" / "+(Double.isNaN(e.moonset)?"No moonset today":timed(e.moonset,y,m,d)));
        row(c[1],"Tithi",e.base.tithiName+" ("+e.base.paksha+") "+after(e.tithiEnd,t->Panchang.currentTithiName(t)+" ("+Panchang.currentPaksha(t)+")",Panchang::tithiEndJd,y,m,d));row(c[1],"Nakshatra",e.base.nakshatra+" "+after(e.nakshatraEnd,Panchang::currentNakshatra,Panchang::nakshatraEndJd,y,m,d));row(c[1],"Yoga",Panchang.yoga(e.base.sunriseJd)+" "+after(e.yogaEnd,Panchang::yoga,Panchang::yogaEndJd,y,m,d));row(c[1],"Karana",Panchang.karana(e.base.sunriseJd)+" "+afterTwice(e.karanaEnd,Panchang::karana,Panchang::karanaEndJd,y,m,d));ImageView phase=new ImageView(this);phase.setImageDrawable(new PanchangDisplay.MoonDrawable(e.base.sunriseJd));phase.setContentDescription("Moon phase");content.addView(phase,new LinearLayout.LayoutParams(dp(54),dp(54)));row(c[1],"Moon sign",Panchang.moonRashi(e.base.sunriseJd)+" till "+timed(e.moonRashiEnd,y,m,d));row(c[1],"Sun sign",Panchang.sunRashi(e.base.sunriseJd)+" till "+timed(e.sunRashiEnd,y,m,d));
        row(c[2],"Rahu Kalam",tm(e.rahuStart)+" - "+tm(e.rahuEnd));row(c[2],"Yamaganda",tm(e.yamagandaStart)+" - "+tm(e.yamagandaEnd));row(c[2],"Gulikai Kalam",tm(e.gulikaStart)+" - "+tm(e.gulikaEnd));String ab=tm(e.abhijitStart)+" - "+tm(e.abhijitEnd);Calendar now=Calendar.getInstance(IST);if(y==now.get(Calendar.YEAR)&&m==now.get(Calendar.MONTH)+1&&d==now.get(Calendar.DAY_OF_MONTH)){double n=PanchangDisplay.jdNow();if(n>=e.abhijitStart&&n<=e.abhijitEnd)ab="NOW  \u00B7  "+ab;}if(wd.get(Calendar.DAY_OF_WEEK)==Calendar.WEDNESDAY)ab+=" (not observed on Wednesday)";row(c[2],"Abhijit Muhurta",ab);row(c[2],"Festival",e.base.festival.isEmpty()?"No listed observance":e.base.festival);
        TextView credit=label("Computed offline (Lahiri)",12,false);content.addView(credit);main.removeCallbacks(todayRefresh);if(y==now.get(Calendar.YEAR)&&m==now.get(Calendar.MONTH)+1&&d==now.get(Calendar.DAY_OF_MONTH))scheduleTodayRefresh(e,now); }
    private void scheduleTodayRefresh(Panchang.DayEvents e,Calendar now){double jd=PanchangDisplay.jdNow(),next=Double.POSITIVE_INFINITY;double[] changes={Panchang.tithiEndJd(jd),Panchang.nakshatraEndJd(jd),Panchang.yogaEndJd(jd),Panchang.karanaEndJd(jd),Panchang.moonRashiEndJd(jd),Panchang.solarRashiEndJd(jd),e.rahuStart,e.rahuEnd,e.yamagandaStart,e.yamagandaEnd,e.gulikaStart,e.gulikaEnd,e.abhijitStart,e.abhijitEnd};for(double x:changes)if(x>jd)next=Math.min(next,x);Calendar midnight=(Calendar)now.clone();midnight.add(Calendar.DAY_OF_MONTH,1);midnight.set(Calendar.HOUR_OF_DAY,0);midnight.set(Calendar.MINUTE,0);midnight.set(Calendar.SECOND,0);midnight.set(Calendar.MILLISECOND,0);long delay=Math.min(midnight.getTimeInMillis()-System.currentTimeMillis(),(long)((next-jd)*86400000));main.postDelayed(todayRefresh,Math.max(1000,delay));}
    private void openPicker(){pickerOpen=true;Calendar v=(Calendar)selected.clone();LinearLayout panel=new LinearLayout(this);panel.setPadding(dp(16),dp(16),dp(16),dp(16));String[] months=new SimpleDateFormat("MMMM",Locale.US).getDateFormatSymbols().getMonths();int[] vals={v.get(Calendar.DAY_OF_MONTH),v.get(Calendar.MONTH)+1,v.get(Calendar.YEAR)};String[] prefix={"Day ","Month ","Year "};TextView[] fields=new TextView[3];final int[] focus={0};final AlertDialog[] dialogRef={null};for(int i=0;i<3;i++){final int ix=i;fields[i]=label(prefix[i]+(i==1?months[vals[i]-1]:vals[i]),24,true);fields[i].setFocusable(true);fields[i].setBackgroundResource(R.drawable.calendar_focus);fields[i].setOnKeyListener((view,key,event)->{if(event.getAction()!=KeyEvent.ACTION_DOWN)return true;int k=event.getKeyCode();if(k==KeyEvent.KEYCODE_DPAD_LEFT||k==KeyEvent.KEYCODE_DPAD_RIGHT){focus[0]=Math.max(0,Math.min(2,ix+(k==KeyEvent.KEYCODE_DPAD_LEFT?-1:1)));fields[focus[0]].requestFocus();return true;}if(k==KeyEvent.KEYCODE_DPAD_UP||k==KeyEvent.KEYCODE_DPAD_DOWN){int delta=k==KeyEvent.KEYCODE_DPAD_UP?1:-1;vals[ix]+=delta;if(ix==0)vals[ix]=Math.max(1,Math.min(Panchang.clampDay(vals[2],vals[1],vals[0]),vals[ix]));else if(ix==1)vals[ix]=Math.max(1,Math.min(12,vals[ix]));else vals[ix]=Math.max(1900,Math.min(2100,vals[ix]));vals[0]=Panchang.clampDay(vals[2],vals[1],vals[0]);fields[ix].setText(prefix[ix]+(ix==1?months[vals[ix]-1]:vals[ix]));fields[0].setText(prefix[0]+vals[0]);return true;}if(k==KeyEvent.KEYCODE_BACK){if(dialogRef[0]!=null)dialogRef[0].cancel();pickerOpen=false;return true;}if(k==KeyEvent.KEYCODE_DPAD_CENTER||k==KeyEvent.KEYCODE_ENTER){selected.set(vals[2],vals[1]-1,1);selected.set(Calendar.DAY_OF_MONTH,Panchang.clampDay(vals[2],vals[1],vals[0]));pickerOpen=false;render();return true;}return false;});panel.addView(fields[i],new LinearLayout.LayoutParams(0,dp(72),1));}AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Pick date  \u00B7  LEFT/RIGHT select, UP/DOWN change, OK apply").setView(panel).setOnCancelListener(x->pickerOpen=false).create();dialogRef[0]=dialog;dialog.setOnDismissListener(x->pickerOpen=false);dialog.show();fields[0].requestFocus(); }
    
    @Override protected void onDestroy(){generation++;main.removeCallbacks(todayRefresh);super.onDestroy();worker.shutdownNow();}
}
